#include "Plugin.cpp"
#include <iostream>
int main(){juce::ScopedJuceInitialiser_GUI init;Processor p;p.prepareToPlay(48000,256);juce::MidiBuffer m;auto set=[&](const char* id,float v){auto* a=p.state.getParameter(id);a->setValueNotifyingHost(a->convertTo0to1(v));};auto tone=[&](float hz){double out=0,in=0;for(int k=0;k<400;++k){juce::AudioBuffer<float>b(2,256);for(int n=0;n<256;++n){float x=0.25f*std::sin(juce::MathConstants<double>::twoPi*hz*(k*256+n)/48000);b.setSample(0,n,x);b.setSample(1,n,x);if(k>200)in+=x*x;}p.processBlock(b,m);for(int n=0;n<256;++n){if(!std::isfinite(b.getSample(0,n)))std::exit(2);if(k>200)out+=b.getSample(0,n)*b.getSample(0,n);}}return std::sqrt(out/in);};set("freq",6000);set("amount",100);set("threshold",-35);double body=tone(200),sib=tone(6000);set("mix",0);double dry=tone(6000);set("mix",100);set("bypass",1);double bypass=tone(6000);juce::MemoryBlock saved;p.getStateInformation(saved);set("freq",9000);p.setStateInformation(saved.getData(),(int)saved.getSize());std::cout<<"body="<<body<<" sibilance="<<sib<<" dry="<<dry<<" bypass="<<bypass<<" restored="<<p.state.getRawParameterValue("freq")->load()<<std::endl;return body>0.95&&sib<0.6&&std::abs(dry-1)<0.001&&std::abs(bypass-1)<0.001&&p.state.getRawParameterValue("freq")->load()==6000?0:1;}

